    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
                                      
    try {
        // 1. Validação de campos vazios
        if (jTpeso.getText().isEmpty() || jTaltura.getText().isEmpty() || jTidade.getText().isEmpty() || 
            jTprot.getText().isEmpty() || jTgord.getText().isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(this, "Por favor, preencha todos os campos numéricos.");
            return;
        }

        // 2. Coleta de Dados
        double peso = Double.parseDouble(jTpeso.getText().replace(",", "."));
        double altura = Double.parseDouble(jTaltura.getText().replace(",", "."));
        int idade = Integer.parseInt(jTidade.getText());
        double fProt = Double.parseDouble(jTprot.getText().replace(",", "."));
        double fGord = Double.parseDouble(jTgord.getText().replace(",", "."));

        // 3. Cálculo da TMB (Mifflin-St Jeor)
        double tmb = 0;
        if (jRmasc.isSelected()) {
            tmb = (10 * peso) + (6.25 * altura) - (5 * idade) + 5;
        } else if (jRfem.isSelected()) {
            tmb = (10 * peso) + (6.25 * altura) - (5 * idade) - 161;
        } else {
            // Caso selecione "Outro", usamos uma média ou pedimos seleção
            tmb = (10 * peso) + (6.25 * altura) - (5 * idade) - 80; 
        }

        // 4. Fator de Atividade (Verificando qual RadioButton está marcado)
        double fator = 1.2;
        if (jRseden.isSelected()) fator = 1.2;
        else if (jRleve.isSelected()) fator = 1.375;
        else if (jRmod.isSelected()) fator = 1.55;
        else if (jRint.isSelected()) fator = 1.725;
        else if (jRatleta.isSelected()) fator = 1.9;

        double tdee = tmb * fator;

        // 5. Objetivo (Ajuste de Calorias)
        double caloriasAlvo = tdee;
        String metaNome = "Manutenção";
        
        if (jRganho.isSelected()) {
            caloriasAlvo = tdee + 300;
            metaNome = "Ganho de Massa";
        } else if (jRemag.isSelected()) {
            caloriasAlvo = tdee - 500;
            metaNome = "Emagrecimento";
        }

        // 6. Cálculo de Macros e Check de Segurança
        double gProt = peso * fProt;
        double gGord = peso * fGord;
        double calProtGord = (gProt * 4) + (gGord * 9);

        if (calProtGord >= caloriasAlvo) {
            javax.swing.JOptionPane.showMessageDialog(this, "Atenção: A gordura e proteína excedem a meta calórica!");
            return;
        }

        double gCarb = (caloriasAlvo - calProtGord) / 4;

        // 7. Exibição no Painel de Resultados (jLresultado ou área correspondente)
        // Dica: Use um JLabel grande ou JTextArea para exibir o texto abaixo
// Versão simplificada sem cores e sem margens extras
        String resumo = "<html>"
        + "RELATÓRIO NUTRICIONAL<br>"
        + "Gasto Diário (TDEE): " + String.format("%.0f", tdee) + " kcal<br>"
        + "Meta (" + metaNome + "): " + String.format("%.0f", caloriasAlvo) + " kcal<br>"
        + "--------------------------------<br>"
        + "Macros Diários:<br>"
        + "• Proteína: " + String.format("%.1f", gProt) + "g<br>"
        + "• Gordura: " + String.format("%.1f", gGord) + "g<br>"
        + "• Carboidrato: " + String.format("%.1f", gCarb) + "g"
        + "</html>";

jLresultado.setText(resumo);

    } catch (NumberFormatException e) {
        javax.swing.JOptionPane.showMessageDialog(this, "Erro: Use apenas números e pontos/vírgulas.");
    }

    }//GEN-LAST:event_jButton1ActionPerformed

    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
                                         
    // Limpar TextFields
    {
    jTpeso.setText("");
    jTaltura.setText("");
    jTidade.setText("");
    jTprot.setText("");
    jTgord.setText("");
    
    // Resetar RadioButtons (Supondo que você criou ButtonGroups)
    jRmasc.setSelected(true); // Padrão
    jRseden.setSelected(true);
    jRmanu.setSelected(true);
    
    // Limpar Resultado
    jLresultado.setText("");
    
    // Focar no início
    jTpeso.requestFocus();
    }
    }//GEN-LAST:event_jButton2ActionPerformed

